import com.github.javaparser.JavaParser;
import com.github.javaparser.ast.CompilationUnit;
import com.github.javaparser.ast.expr.MethodCallExpr;
import com.github.javaparser.ast.visitor.VoidVisitorAdapter;
import com.github.javaparser.resolution.declarations.ResolvedMethodDeclaration;
import com.github.javaparser.resolution.model.SymbolReference;
import com.github.javaparser.symbolsolver.javaparsermodel.JavaParserFacade;
import com.github.javaparser.symbolsolver.resolution.typesolvers.ReflectionTypeSolver;

public class VerifyIssue {
    public static void main(String[] args) {
        String fileContent = "package my.example;\n"
            + "public class MyExample {\n"
            + "  public static void main(String[] args) {\n"
            + "    \"Hello single %s!\".formatted(\"world\");\n"
            + "    \"\"\"\n"
            + "        Hello multiple %s!\n"
            + "        \"\"\".formatted(\"world\");\n"
            + "    String.format(\"\"\"\n"
            + "        Hello %s\n"
            + "        \"\"\", \"world\");\n"
            + "  }\n"
            + "}\n";
        ReflectionTypeSolver solver = new ReflectionTypeSolver(false);
        CompilationUnit compilationUnit = new JavaParser().parse(fileContent).getResult().get();

        new VoidVisitorAdapter<>() {
            public void visit(MethodCallExpr n, Object arg) {
                super.visit(n, arg);
                try {
                    SymbolReference<ResolvedMethodDeclaration> solved =
                        JavaParserFacade.get(solver).solve(n.asMethodCallExpr());
                    System.out.println("Could solve: " + n.replace("\n", "\\n").replace("\r", "")
                        + " as " + solved.getCorrespondingDeclaration().getQualifiedSignature());
                } catch (Exception e) {
                    System.err.println("Could not solve: " + n.replace("\n", "\\n").replace("\r", "")
                        + " -> " + e.getMessage());
                }
            }
        }.visit(compilationUnit.getTypes(), null);
    }
}

part.text:
Fixed. The issue was in `TypeExtractor.java:286` — the symbol solver's type extractor threw `UnsupportedOperationException` for `TextBlockLiteralExpr` (inherited from `DefaultVisitorAdapter`, which throws for it), so the scope of `"""...""".formatted(...)` couldn't be resolved to `java.lang.String`.

The fix adds an override in `javaparser-symbol-solver-core/src/main/java/com/github/javaparser/symbolsolver/javaparsermodel/TypeExtractor.java`:

```java
@Override
public ResolvedType visit(TextBlockLiteralExpr node, Boolean solveLambdas) {
    return stringReferenceType;
}
```

Verification:
- Compiled a reproduction of the issue: the text-block `.formatted("world")` call now resolves to `java.lang.String.formatted(java.lang.Object...)`, and `String.format("""...""", ...)` also resolves.
- Full `javaparser-symbol-solver-testing` suite: 1936 tests run, 0 failures, 0 errors (33 skipped).
